const pathParameter = (
  name: string,
  description?: string,
  enumValues?: string[],
) => ({
  name,
  in: "path",
  required: true,
  description,
  schema: {
    type: "string",
    enum: enumValues && enumValues.length > 0 ? enumValues : undefined,
  },
});

const queryParameter = (
  name: string,
  schema: Record<string, unknown> = { type: "string" },
  description?: string,
) => ({
  name,
  in: "query",
  required: false,
  description,
  schema,
});

