          [`/api/sites/${site.id}/visitor-auth/email-change`]: {
  "post": {
    "tags": [
      "Website accounts"
    ],
    "operationId": "requestBackyVisitorEmailChange",
    "x-backy-auth-boundary": "site-visitor-only",
    "x-backy-production-provider-proof": "pending",
    "security": [
      {
        "BackyVisitorSession": []
      },
      {
        "BackyVisitorBearer": []
      },
      {
        "BackyVisitorCookie": []
      }
    ],
    "summary": "Request website account email change",
    "description": "Current active website session and fresh provider password authorize initiation. Atomic subject-wide session/recovery revocation occurs before provider PUT; later provider failure leaves sessions revoked and clears the site cookie. Exact server-approved returnUrl. Confirmation emails and provider200 are not completion. No persistent pending email or provider token.",
    "parameters": [
      {
        "name": "Origin",
        "in": "header",
        "required": true,
        "schema": {
          "type": "string",
          "format": "uri"
        },
        "description": "Exact approved website Origin header required."
      }
    ],
    "requestBody": {
      "required": true,
      "content": {
        "application/json": {
          "schema": {
            "$ref": "#/components/schemas/VisitorEmailChangeRequest"
          }
        }
      }
    },
    "responses": {
      "202": {
        "description": "Private no-store result; sign in again after confirmation",
        "content": {
          "application/json": {
            "schema": {
              "$ref": "#/components/schemas/VisitorEmailChangePendingEnvelope"
            }
          }
        }
      },
      "400": {
        "description": "VISITOR_INVALID_REQUEST or VISITOR_RETURN_URL_DENIED; exact JSON fields and approved return URL required",
        "content": {
          "application/json": {
            "schema": {
              "$ref": "#/components/schemas/VisitorErrorEnvelope"
            }
          }
        }
      },
      "401": {
        "description": "VISITOR_AUTHENTICATION_REQUIRED: session, password, confirmed identity or existing membership unavailable",
        "content": {
          "application/json": {
            "schema": {
              "$ref": "#/components/schemas/VisitorErrorEnvelope"
            }
          }
        }
      },
      "403": {
        "description": "Exact approved Origin/published enabled website required; operator identities denied",
        "content": {
          "application/json": {
            "schema": {
              "$ref": "#/components/schemas/VisitorErrorEnvelope"
            }
          }
        }
      },
      "404": {
        "description": "SITE_NOT_FOUND",
        "content": {
          "application/json": {
            "schema": {
              "$ref": "#/components/schemas/VisitorErrorEnvelope"
            }
          }
        }
      },
      "409": {
        "description": "VISITOR_EMAIL_CHANGE_CONFLICT: identity or current email collision; retry only after resolving",
        "content": {
          "application/json": {
            "schema": {
              "$ref": "#/components/schemas/VisitorErrorEnvelope"
            }
          }
        }
      },
      "413": {
        "description": "VISITOR_REQUEST_TOO_LARGE: at most16KiB",
        "content": {
          "application/json": {
            "schema": {
              "$ref": "#/components/schemas/VisitorErrorEnvelope"
            }
          }
        }
      },
      "415": {
        "description": "VISITOR_JSON_REQUIRED",
        "content": {
          "application/json": {
            "schema": {
              "$ref": "#/components/schemas/VisitorErrorEnvelope"
            }
          }
        }
      },
      "429": {
        "description": "VISITOR_RATE_LIMITED",
        "content": {
          "application/json": {
            "schema": {
              "$ref": "#/components/schemas/VisitorErrorEnvelope"
            }
          }
        }
      },
      "503": {
        "description": "VISITOR_AUTH_UNAVAILABLE or VISITOR_EMAIL_CHANGE_UNAVAILABLE; no provider tokens exposed",
        "content": {
          "application/json": {
            "schema": {
              "$ref": "#/components/schemas/VisitorErrorEnvelope"
            }
          }
        }
      }
    }
  }
},
