[`/api/admin/sites/${site.id}/forms/attachment-cleanup`]: {
  "get": {
    "operationId": "listAdminFormAttachmentCleanup",
    "summary": "List pending private form attachment cleanup",
    "description": "Requires forms.delete for the selected site. Returns the complete verified pending queue, including cleanup retained after the form was deleted. Only form IDs and attachment counts are exposed. No attachment bytes, filenames, submission values, or storage paths are returned. If the private inventory cannot be verified completely, the request fails with 503 instead of returning a partial queue. Resume a job by repeating the authorized DELETE for its formId.",
    "tags": [
      "Interactions"
    ],
    "security": [
      {
        "BackyAdminSession": []
      },
      {
        "BackyAdminKey": []
      }
    ],
    "x-backy-permission": "forms.delete",
    "responses": {
      "200": {
        "description": "Verified pending cleanup jobs; an empty array means no pending jobs.",
        "content": {
          "application/json": {
            "schema": {
              "$ref": "#/components/schemas/FormAttachmentCleanupEnvelope"
            }
          }
        },
        "headers": {
          "Cache-Control": {
            "description": "Private response must not be cached.",
            "schema": {
              "type": "string",
              "const": "private, no-store"
            }
          }
        }
      },
      "401": {
        "description": "Authentication required",
        "content": {
          "application/json": {
            "schema": {
              "$ref": "#/components/schemas/ErrorEnvelope"
            }
          }
        }
      },
      "403": {
        "description": "Site-scoped forms.delete permission required",
        "content": {
          "application/json": {
            "schema": {
              "$ref": "#/components/schemas/ErrorEnvelope"
            }
          }
        }
      },
      "404": {
        "description": "Site or form not found in this authorized scope",
        "content": {
          "application/json": {
            "schema": {
              "$ref": "#/components/schemas/ErrorEnvelope"
            }
          }
        }
      },
      "503": {
        "description": "Private cleanup inventory unavailable, incomplete, or invalid. Restore private storage or repository access and retry; no partial inventory is returned.",
        "content": {
          "application/json": {
            "schema": {
              "$ref": "#/components/schemas/ErrorEnvelope"
            }
          }
        }
      }
    }
  }
},
