            AdminInteractiveComponentReviewedPreview: {
  "type": "object",
  "required": [
    "siteId",
    "source",
    "target",
    "targetFingerprint",
    "targets"
  ],
  "additionalProperties": false,
  "description": "Exact preview identity and document snapshots. Optional for historical callers; reviewed admin UI always sends it. Any document addition/removal/content or target-definition drift returns409 before writes. Server-side per-document CAS additionally guards apply-time author edits. No public live-render certification.",
  "properties": {
    "siteId": {
      "type": "string"
    },
    "source": {
      "type": "object",
      "required": [
        "componentKey",
        "version"
      ],
      "additionalProperties": false,
      "properties": {
        "componentKey": {
          "type": "string"
        },
        "version": {
          "type": "string"
        }
      }
    },
    "target": {
      "type": "object",
      "required": [
        "componentKey",
        "version"
      ],
      "additionalProperties": false,
      "properties": {
        "componentKey": {
          "type": "string"
        },
        "version": {
          "type": "string"
        }
      }
    },
    "targetFingerprint": {
      "type": "string",
      "pattern": "^[a-f0-9]{64}$"
    },
    "targets": {
      "type": "array",
      "maxItems": 200000,
      "items": {
        "type": "object",
        "required": [
          "targetType",
          "targetId",
          "contentFingerprint"
        ],
        "additionalProperties": false,
        "properties": {
          "targetType": {
            "enum": [
              "page",
              "post"
            ]
          },
          "targetId": {
            "type": "string",
            "minLength": 1,
            "maxLength": 160
          },
          "contentFingerprint": {
            "type": "string",
            "pattern": "^[a-f0-9]{64}$"
          }
        }
      }
    }
  }
},
