            FrontendDomCaptureEvidence: {
              "type": "object",
              "required": [
                "schemaVersion",
                "source",
                "capturedAt",
                "viewport",
                "expectedCount",
                "capturedCount",
                "limitations"
              ],
              "properties": {
                "schemaVersion": {
                  "const": "backy.frontend-dom-evidence.v1"
                },
                "source": {
                  "const": "browser-dom"
                },
                "capturedAt": {
                  "type": "string",
                  "format": "date-time"
                },
                "viewport": {
                  "type": "object",
                  "required": [
                    "width",
                    "height"
                  ],
                  "properties": {
                    "width": {
                      "type": "number",
                      "minimum": 0,
                      "maximum": 100000
                    },
                    "height": {
                      "type": "number",
                      "minimum": 0,
                      "maximum": 100000
                    }
                  }
                },
                "expectedCount": {
                  "type": "integer",
                  "minimum": 0,
                  "maximum": 10000
                },
                "capturedCount": {
                  "type": "integer",
                  "minimum": 0,
                  "maximum": 10000
                },
                "limitations": {
                  "type": "array",
                  "maxItems": 32,
                  "items": {
                    "enum": [
                      "expected-inventory.unknown",
                      "identity.missing",
                      "revision.missing",
                      "iframe.unobserved",
                      "inventory.limit",
                      "dom-walk.limit",
                      "shadow-dom.unobserved",
                      "element-id.invalid",
                      "element-id.duplicate",
                      "element-type.unknown",
                      "parent.ambiguous",
                      "visibility.hidden",
                      "geometry.unmapped",
                      "geometry.invalid",
                      "inventory.byte-limit",
                      "expected-element.absent",
                      "element.unregistered",
                      "mapping.unknown"
                    ]
                  }
                }
              },
              "description": "Optional bounded browser DOM evidence. Counts/limitations/revision affect completeness; capturedCount must equal observed element count. Geometry/identity evidence never certifies interactive or animation behavior."
            },
            FrontendElementDomEvidence: {
              "type": "object",
              "required": [
                "rect",
                "visibility",
                "positioning",
                "transformed"
              ],
              "properties": {
                "rect": {
                  "type": "object",
                  "required": [
                    "x",
                    "y",
                    "width",
                    "height"
                  ],
                  "properties": {
                    "x": {
                      "type": "number",
                      "minimum": -10000000.0,
                      "maximum": 10000000.0
                    },
                    "y": {
                      "type": "number",
                      "minimum": -10000000.0,
                      "maximum": 10000000.0
                    },
                    "width": {
                      "type": "number",
                      "minimum": 0,
                      "maximum": 10000000.0
                    },
                    "height": {
                      "type": "number",
                      "minimum": 0,
                      "maximum": 10000000.0
                    }
                  }
                },
                "visibility": {
                  "enum": [
                    "rendered",
                    "hidden"
                  ]
                },
                "positioning": {
                  "enum": [
                    "absolute",
                    "fixed",
                    "relative",
                    "static",
                    "sticky",
                    "unknown"
                  ]
                },
                "transformed": {
                  "type": "boolean"
                }
              }
            },
